Object target = parameters.get("target");
String expected = (String) parameters.get("expected_path");
String requested = (String) parameters.get("new_path");
String before;
String after;
if (target instanceof AutoUpdateTable) {
    TableUpdate update = ((AutoUpdateTable) target).getTableUpdate();
    before = update.getFilePathCso().getFilePath();
    if (!expected.equals(before)) throw new IllegalStateException("Export path changed before update");
    update.setFilePath(requested);
    after = update.getFilePathCso().getFilePath();
} else if (target instanceof UpdatePlot) {
    PlotUpdate update = ((UpdatePlot) target).getPlotUpdate();
    before = String.valueOf(update.getAnimationFilePath());
    if (!expected.equals(before)) throw new IllegalStateException("Export path changed before update");
    update.setAnimationFilePath(requested);
    after = String.valueOf(update.getAnimationFilePath());
} else {
    throw new IllegalArgumentException("An AutoUpdateTable or UpdatePlot is required");
}
result.put("before_path", before);
result.put("after_path", after);
if (!requested.equals(after)) throw new IllegalStateException("Export directory readback mismatch");
